sourceEventSeqs;\n\t\t\t}\n\n\t\t\tresultSeed.push(cloned);\n\t\t}\n\n\t\treturn resultSeed;\n\t} catch (err) {\n\t\tconsole.warn(\"[dsh-subagent-role-router:fork-window] Slicing error, safely returning null:\", err?.message || err);\n\t\treturn null;\n\t}\n}"
